def rep(old,new,n=1):
    global s
    if old not in s: raise SystemExit('trecho não encontrado: '+old[:80])
    s=s.replace(old,new,n)

def sub(pattern,repl,n=1):
    global s
    s2,c=re.subn(pattern,repl,s,count=n,flags=re.S)
    if c != n: raise SystemExit(f'regex falhou {c}: '+pattern[:80])
    s=s2

