sub(r'    // ALFA-DEV:\n// AUTORIZAÇÃO NO FRONTEND\..*?    /\*\n      CONFIGURAÇÃO NECESSÁRIA NO FIREBASE', '''    // ALFA-DEV:\n    // ACESSO COMPARTILHADO DO ESCRITÓRIO — v1.8.0.\n    // O Authentication continua protegendo o Firestore, mas não existe mais perfil por funcionário/e-mail.\n    // A conta abaixo é apenas a credencial técnica do escritório; funcionários são escolhidos na interface.\n    // Não trocar por login anônimo e não abrir regras do Firestore para o público.\n    const OFFICE_LOGIN_EMAIL = "alfafiscalto@gmail.com";\n    const SHARED_ACCESS_PROFILE = { name: "equipe", role: "Acesso compartilhado", employee: null };\n\n    function normalizeEmail(email) { return String(email || "").trim().toLowerCase(); }\n    function isAllowedUser(email) { return normalizeEmail(email) === normalizeEmail(OFFICE_LOGIN_EMAIL); }\n    function isAdminUser() { return Boolean(currentUser && isAllowedUser(currentUser.email)); }\n    function currentEmployeeName() { return null; }\n\n    // Os clientes são carregados exclusivamente da coleção "clientes" do Firestore.\n    // Não há lista fixa de clientes neste HTML.\n\n    /*\n      CONFIGURAÇÃO NECESSÁRIA NO FIREBASE''')
