sub(r'    function setView\(view\) \{.*?\n    \}\n\n    function monthValue', '''    function setView(view) {\n      currentView = view;\n      document.querySelectorAll("[data-view]").forEach(btn => btn.classList.toggle("active", btn.dataset.view === view));\n      taskSections.forEach(section => { if (section) section.style.display = view === "tasks" ? "" : "none"; });\n      homeSection.classList.toggle("active", view === "home");\n      clientsSection.classList.toggle("active", view === "clients");\n      employeesSection.classList.toggle("active", view === "employees");\n      reportsSection.classList.toggle("active", view === "reports");\n      render();\n    }\n\n    function monthValue''')
sub(r'    function updateEmployeeSelector\(\) \{.*?\n    \}\n\n    function renderEmployeeChoices', '''    function updateEmployeeSelector() {\n      if (!selectedEmployeeLabel || !selectedEmployeeDot || !selectedEmployeeCount || !employeeSelectorBtn) return;\n      const employeeName = selectedEmployee || "todos";\n      selectedEmployeeLabel.textContent = getEmployeeDisplayName(employeeName);\n      selectedEmployeeDot.style.color = getEmployeeColor(employeeName);\n      selectedEmployeeCount.textContent = getEmployeeOpenCount(employeeName);\n      employeeSelectorBtn.disabled = !currentUser;\n      employeeSelectorHint.textContent = currentUser ? "Clique para escolher" : "Entre no sistema";\n    }\n\n    function renderEmployeeChoices''')
sub(r'    function openEmployeeSelectModal\(\) \{.*?\n    \}\n\n    function buildEmployees', '''    function openEmployeeSelectModal() {\n      if (!currentUser) { showToast("Entre no sistema para selecionar um funcionário."); return; }\n      renderEmployeeChoices();\n      employeeSelectModal.classList.add("open");\n      document.body.classList.add("modal-is-open");\n    }\n\n    function closeEmployeeSelectModal() {\n      employeeSelectModal.classList.remove("open");\n      document.body.classList.remove("modal-is-open");\n    }\n\n    function selectEmployee(employeeName, closePicker = false) {\n      selectedEmployee = employeeName || "todos";\n      if (closePicker) closeEmployeeSelectModal();\n      updateEmployeeSelector();\n      const showTasks = () => currentView !== "tasks" ? setView("tasks") : render();\n      if (closePicker) requestAnimationFrame(showTasks); else showTasks();\n    }\n\n    function buildEmployees''')
sub(r'    function buildEmployees\(\) \{.*?\n    \}\n\n    // ALFA-DEV:\n// FILTROS DE TAREFAS\.', '''    function buildEmployees() {\n      employeeInput.innerHTML = "";\n      const reportEmployeeInput = document.getElementById("reportEmployeeInput");\n      const previousReportEmployee = reportEmployeeInput?.value || "todos";\n      if (reportEmployeeInput) reportEmployeeInput.innerHTML = "";\n      employees.forEach(employee => {\n        const inactive = employee.active === false;\n        const label = document.createElement("label");\n        label.className = "employee-check";\n        label.innerHTML = `<input type="checkbox" name="taskEmployees" value="${escapeHTML(employee.name)}" ${inactive ? "disabled" : ""}><span class="employee-check-name"><span class="dot" style="color:${escapeHTML(employee.color)}"></span><span>${escapeHTML(employee.name)}${inactive ? " · inativo" : ""}</span></span>`;\n        employeeInput.appendChild(label);\n      });\n      if (reportEmployeeInput) {\n        reportEmployeeInput.innerHTML = `<option value="todos">Todos</option>`;\n        employees.forEach(employee => { const o=document.createElement("option"); o.value=employee.name; o.textContent=`${employee.name}${employee.active === false ? " (inativo)" : ""}`; reportEmployeeInput.appendChild(o); });\n        reportEmployeeInput.disabled = false;\n        reportEmployeeInput.value = Array.from(reportEmployeeInput.options).some(o => o.value === previousReportEmployee) ? previousReportEmployee : "todos";\n      }\n      if (!selectedEmployee || (selectedEmployee !== "todos" && !getEmployeeByName(selectedEmployee))) selectedEmployee = "todos";\n      updateEmployeeSelector();\n    }\n\n    // ALFA-DEV:\n// FILTROS DE TAREFAS.''')
sub(r'    function getFilteredTasks\(\) \{.*?\n    \}\n\n    function isOverdue', '''    function getFilteredTasks() {\n      const searchTerm = document.getElementById("searchInput").value.trim().toLowerCase();\n      const statusFilter = document.getElementById("statusFilter").value;\n      const priorityFilter = document.getElementById("priorityFilter").value;\n      return tasks.filter(task => {\n        const assigneeText = getTaskAssigneeText(task);\n        const byEmployee = selectedEmployee === "todos" || taskHasEmployee(task, selectedEmployee);\n        const byStatus = statusFilter === "todos" || task.status === statusFilter;\n        const byPriority = priorityFilter === "todas" || task.priority === priorityFilter;\n        const text = [assigneeText, task.clientAlias, task.clientName, task.clientDocument, task.serviceType, task.description, task.observation, task.status, task.priority].filter(Boolean).join(" ").toLowerCase();\n        return byEmployee && byStatus && byPriority && (!searchTerm || text.includes(searchTerm));\n      });\n    }\n\n    function isOverdue''')
