sub(r'    function render\(\) \{.*?\n    \}\n\n    function openModal', '''    function renderTaskView() {\n      if (selectedEmployee === "todos") document.documentElement.style.setProperty("--red", "#e50914");\n      renderHeader();\n      const filtered = getFilteredTasks();\n      renderStats(filtered);\n      renderColumn("listPendente", filtered.filter(task => task.status === "pendente"));\n      renderColumn("listAndamento", filtered.filter(task => task.status === "andamento"));\n      renderColumn("listConcluido", filtered.filter(task => task.status === "concluido"));\n    }\n\n    function render() {\n      updateEmployeeSelector();\n      if (currentView === "tasks") return renderTaskView();\n      if (currentView === "home") return renderHomeDashboard();\n      if (currentView === "clients") return renderClients();\n      if (currentView === "employees") return renderEmployeesManagement();\n      if (currentView === "reports") return generateReport();\n    }\n\n    function openModal''')
