sub(r'    // ALFA-DEV:\n// LOGIN\..*?\n    \}\n\n    async function handleLogout', '''    // ALFA-DEV:\n    // LOGIN COMPARTILHADO — v1.8.0. A interface pede só a senha; o e-mail técnico fica fixo.\n    async function handleLogin(event) {\n      event.preventDefault();\n      if (!firebaseReady) { showToast("Configure o Firebase antes de fazer login."); return; }\n      try { await signInWithEmailAndPassword(auth, OFFICE_LOGIN_EMAIL, document.getElementById("loginPassword").value); }\n      catch (error) { console.error(error); showToast("Senha não autorizada. Confira a senha da conta do escritório no Firebase Authentication."); }\n    }\n\n    async function handleLogout''')
